"""Whether each settled claim's receipt is actually in the ledger right now.

Uses one period `list` per month rather than per-entry `show`: `list` is a flat
monthly fee in the vendor contract, `show` is billed per call (see EXP-412).
Nothing is cached, so every screen open reflects the ledger's current state.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def for_claims(self, claims):
        """Map claim id -> "booked" / "not_booked" (settled) or None (not settled)."""
        settled = [c for c in claims if c.status == POSTED and c.receipt]
        receipts_by_month = {}
        for month in sorted({c.spent_on[:7] for c in settled}):
            date_from, date_to = month_bounds(month)
            rows = self.ledger.list_rows(date_from, date_to)
            receipts_by_month[month] = {row.receipt for row in rows}
        status = {c.claim_id: None for c in claims}
        for claim in settled:
            booked = claim.receipt in receipts_by_month[claim.spent_on[:7]]
            status[claim.claim_id] = "booked" if booked else "not_booked"
        return status

